CREATE OR REPLACE FUNCTION download.et_update_size_batches(parameter json, ref refcursor)
 RETURNS refcursor
 LANGUAGE plpgsql
AS $function$

declare 
nDPid uuid;
jBatch jsonb;
bIsLast boolean;
BEGIN

nDPid := parameter ->> 'nDPid';
jBatch := parameter ->> 'jBatch';
bIsLast := parameter ->> 'bIsLast';
