with tbl as (
	select "bd" "nBundledetailid","b" "nBatchid","s" "cSize","x" "isFileExists","t" "cBatchType"
	from jsonb_to_recordset(jBatch) as ("bd" uuid,"b" int,"s" text, "x" boolean,"t" text)
)
update download."ProcessBatchs" b set "nBatchid" = t."nBatchid", "cSize" = t."cSize", "isFileExists" = t."isFileExists", "cBatchType" = t."cBatchType"
from tbl t where b."nDPid" = nDPid and b."nBundledetailid" = t."nBundledetailid";

 if(bIsLast = true)then

	update download."ProcessMaster" set "isBatchUpdated" = true 
	where "nDPid" = nDPid;

 end if;

open ref for
select 1 as msg,'Batch Updated' as value
;

RETURN ref;                                                       -- Return the cursor to the caller
    END;
$function$
